-- Native workflow notifications use225 transport; receipts never approve HR.
CREATE TABLE ty_nx_rule(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),profile_id bigint REFERENCES ty_ix_profile(id),
 code text NOT NULL,name text NOT NULL,version integer NOT NULL CHECK(version>0),event_categories text[] NOT NULL,business_types text[] NOT NULL DEFAULT '{}',
 origin text NOT NULL,evidence_ref text NOT NULL,profile_revision integer,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','disabled')),created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),
 created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,revision integer NOT NULL DEFAULT 1,
 CHECK(cardinality(event_categories)>0 AND event_categories<@ARRAY['task','copy','result']::text[]),
 CHECK((profile_id IS NULL)=(profile_revision IS NULL)),CHECK(status<>'approved'OR(approved_by IS NOT NULL AND approved_at IS NOT NULL AND profile_id IS NOT NULL)),UNIQUE(group_id,code,version)
);
CREATE TABLE ty_nx_event(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_key text NOT NULL UNIQUE,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 instance_id bigint NOT NULL REFERENCES ty_workflow_instance(id),task_id bigint REFERENCES ty_workflow_task(id),
 recipient_account_id bigint NOT NULL REFERENCES sys_account(id),recipient_person_id bigint REFERENCES ty_person(id),node_id text NOT NULL,
 category text NOT NULL CHECK(category IN('task','copy','result')),outcome text,
 state text NOT NULL DEFAULT'pending'CHECK(state IN('pending','processed')),created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz
);
CREATE TABLE ty_nx_delivery(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,public_key text NOT NULL UNIQUE CHECK(public_key~'^[a-f0-9]{32}$'),
 event_id bigint NOT NULL REFERENCES ty_nx_event(id),rule_id bigint NOT NULL REFERENCES ty_nx_rule(id),group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),profile_id bigint NOT NULL REFERENCES ty_ix_profile(id),
 instance_id bigint NOT NULL REFERENCES ty_workflow_instance(id),task_id bigint REFERENCES ty_workflow_task(id),recipient_account_id bigint NOT NULL REFERENCES sys_account(id),recipient_person_id bigint REFERENCES ty_person(id),
 identity_id bigint REFERENCES ty_ix_identity(id),identity_revision integer,recipient_external_id text,
 job_id bigint UNIQUE REFERENCES ty_ix_job(id),transport_receipt_id bigint REFERENCES ty_ix_delivery_receipt(id),state text NOT NULL DEFAULT'pending'CHECK(state IN('pending','queued','blocked','closed')),
 acceptance_state text NOT NULL DEFAULT'not_reported'CHECK(acceptance_state IN('not_reported','provider_accepted','failed','unknown')),
 delivery_state text NOT NULL DEFAULT'not_reported'CHECK(delivery_state IN('not_reported','implied_by_read')),
 read_state text NOT NULL DEFAULT'not_reported'CHECK(read_state IN('not_reported','provider_reported_unread','provider_reported_read')),
 platform_result text,reported_read_at timestamptz,observed_read_at timestamptz,remote_id text,error_code text,last_polled_at timestamptz,
 revision integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,rule_id),
 CHECK(num_nonnulls(identity_id,identity_revision,recipient_external_id)IN(0,3))
);
CREATE TABLE ty_nx_observation(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,connection_id bigint NOT NULL REFERENCES ty_integration_connection(id),delivery_id bigint REFERENCES ty_nx_delivery(id),
 envelope_id bigint REFERENCES ty_ix_callback_envelope(id),source_key text NOT NULL,proof_kind text NOT NULL CHECK(proof_kind IN('verified_callback','authenticated_query')),
 provider text NOT NULL CHECK(provider IN('feishu','dingtalk')),remote_id text NOT NULL,recipient_external_id text NOT NULL,
 kind text NOT NULL CHECK(kind IN('read','unread','failed','invalid_recipient','not_reported')),reported_at timestamptz,payload_hash text NOT NULL,
 payload_cipher text NOT NULL,payload_iv text NOT NULL,payload_tag text NOT NULL,
 state text NOT NULL DEFAULT'unmatched'CHECK(state IN('unmatched','applied','blocked')),error_code text,created_at timestamptz NOT NULL DEFAULT now(),applied_at timestamptz,last_checked_at timestamptz,
 UNIQUE(connection_id,source_key),CHECK((proof_kind='verified_callback')=(envelope_id IS NOT NULL))
);
CREATE TABLE ty_nx_receipt_job(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,delivery_id bigint NOT NULL REFERENCES ty_nx_delivery(id),requested_by bigint NOT NULL REFERENCES sys_account(id),
 state text NOT NULL DEFAULT'queued'CHECK(state IN('queued','leased','completed','failed','blocked')),lease_token text,lease_until timestamptz,
 attempts integer NOT NULL DEFAULT 0,error_code text,result jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,
 created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,CHECK((state='leased')=(lease_token IS NOT NULL AND lease_until IS NOT NULL))
);
CREATE UNIQUE INDEX ty_nx_one_receipt_lease ON ty_nx_receipt_job(delivery_id)WHERE state IN('queued','leased');
ALTER TABLE ty_nx_observation ADD COLUMN receipt_job_id bigint REFERENCES ty_nx_receipt_job(id);
ALTER TABLE ty_nx_observation ADD CHECK((proof_kind='authenticated_query')=(receipt_job_id IS NOT NULL));
CREATE FUNCTION fn_ty_nx_capture()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE i public.ty_workflow_instance%ROWTYPE;account bigint;person bigint;category text;task bigint;node text;outcome text;key text;
BEGIN
 SELECT*INTO i FROM public.ty_workflow_instance WHERE id=NEW.instance_id;
 IF TG_TABLE_NAME='ty_workflow_task'THEN account:=NEW.approver_id;task:=NEW.id;node:=NEW.node_id;category:='task';key:='task:'||task;
 ELSE account:=NEW.account_id;node:=NEW.node_id;category:=CASE WHEN node LIKE'sys.result.%'THEN'result'ELSE'copy'END;outcome:=CASE WHEN category='result'THEN substr(node,12)ELSE NULL END;key:=category||':'||i.id||':'||account||CASE WHEN category='result'THEN':'||coalesce(outcome,'')ELSE''END;END IF;
 SELECT CASE WHEN b.account_id IS NOT NULL THEN b.person_id ELSE p.person_id END INTO person FROM public.sys_account a LEFT JOIN public.ty_operator_binding b ON b.account_id=a.id LEFT JOIN public.ty_test_account_profile p ON p.account_id=a.id WHERE a.id=account;
 INSERT INTO public.ty_nx_event(event_key,group_id,company_id,instance_id,task_id,recipient_account_id,recipient_person_id,node_id,category,outcome)VALUES(key,i.group_id,i.company_id,i.id,task,account,person,node,category,outcome)ON CONFLICT(event_key)DO NOTHING;
 RETURN NEW;END$$;
CREATE TRIGGER ty_nx_task_capture AFTER INSERT ON ty_workflow_task FOR EACH ROW EXECUTE FUNCTION fn_ty_nx_capture();
CREATE TRIGGER ty_nx_copy_capture AFTER INSERT ON ty_workflow_copy FOR EACH ROW EXECUTE FUNCTION fn_ty_nx_capture();
CREATE FUNCTION fn_ty_nx_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_nx_rule%ROWTYPE;e public.ty_nx_event%ROWTYPE;c public.ty_integration_connection%ROWTYPE;p public.ty_ix_profile%ROWTYPE;j public.ty_ix_job%ROWTYPE;d public.ty_nx_delivery%ROWTYPE;m public.ty_ix_identity%ROWTYPE;i public.ty_workflow_instance%ROWTYPE;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 通知配置、关联及回执历史保留';END IF;
 IF TG_TABLE_NAME='ty_nx_rule'THEN
  SELECT*INTO c FROM public.ty_integration_connection WHERE id=NEW.connection_id;SELECT*INTO p FROM public.ty_ix_profile WHERE id=NEW.profile_id;
  IF c.group_id<>NEW.group_id OR NEW.company_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company x WHERE x.id=NEW.company_id AND x.group_id=NEW.group_id)OR NEW.profile_id IS NOT NULL AND(p.id IS NULL OR p.connection_id<>c.id)OR c.provider NOT IN('dingtalk','feishu','wecom')OR c.company_id IS NOT NULL AND(NEW.company_id IS NULL OR NOT public.fn_ty_ix_company_contains(c.company_id,NEW.company_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 消息规则须对应同集团及公司范围的企业连接';END IF;
  IF TG_OP='UPDATE'AND(to_jsonb(NEW)-ARRAY['status','approved_by','approved_at','revision'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['status','approved_by','approved_at','revision'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 消息规则来源只建新版本，不改绑';END IF;
  IF TG_OP='UPDATE'AND(NEW.revision<>OLD.revision+1 OR OLD.approved_by IS NOT NULL AND ROW(NEW.approved_by,NEW.approved_at)IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at)OR OLD.status='disabled'AND NEW.status<>'disabled'OR NEW.status IS DISTINCT FROM OLD.status AND NOT(OLD.status='draft'AND NEW.status IN('approved','disabled')OR OLD.status='approved'AND NEW.status='disabled'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已授权的真实HR与规则核准版本不可改绑或复活';END IF;
  IF NEW.status='approved'AND(p.id IS NULL OR public.fn_ty_pr_same_actor(NEW.created_by,NEW.approved_by)OR p.status<>'approved'OR p.revision<>NEW.profile_revision OR c.status<>'active'OR NOT'message.send'=ANY(p.enabled_capabilities))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_FORBIDDEN: 消息规则须独立核准并引用当前已核发送规则';END IF;
 ELSIF TG_TABLE_NAME='ty_nx_event'THEN
  IF TG_OP='UPDATE'AND(to_jsonb(NEW)-ARRAY['state','processed_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','processed_at'])THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 原生通知事件不可换人换单';END IF;
  SELECT*INTO i FROM public.ty_workflow_instance WHERE id=NEW.instance_id;
  IF i.group_id<>NEW.group_id OR i.company_id IS DISTINCT FROM NEW.company_id OR NEW.category='task'AND NOT EXISTS(SELECT 1 FROM public.ty_workflow_task t WHERE t.id=NEW.task_id AND t.instance_id=i.id AND t.approver_id=NEW.recipient_account_id AND t.node_id=NEW.node_id)OR NEW.category<>'task'AND(NEW.task_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.ty_workflow_copy x WHERE x.instance_id=i.id AND x.account_id=NEW.recipient_account_id AND x.node_id=NEW.node_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 通知事件须对应真实原单及收件人';END IF;
 ELSIF TG_TABLE_NAME='ty_nx_delivery'THEN
  SELECT*INTO r FROM public.ty_nx_rule WHERE id=NEW.rule_id;SELECT*INTO e FROM public.ty_nx_event WHERE id=NEW.event_id;
  IF ROW(NEW.group_id,NEW.company_id,NEW.connection_id,NEW.profile_id,NEW.instance_id,NEW.task_id,NEW.recipient_account_id,NEW.recipient_person_id)IS DISTINCT FROM ROW(r.group_id,e.company_id,r.connection_id,r.profile_id,e.instance_id,e.task_id,e.recipient_account_id,e.recipient_person_id)OR e.group_id<>r.group_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 通知投递不得跨公司、换单或换接收人';END IF;
  IF NEW.identity_id IS NOT NULL THEN SELECT*INTO m FROM public.ty_ix_identity WHERE id=NEW.identity_id;IF m.connection_id<>r.connection_id OR m.external_kind<>'person'OR m.person_id<>NEW.recipient_person_id OR m.external_id<>NEW.recipient_external_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 通知平台人员须精确对应收件员工';END IF;END IF;
  IF NEW.job_id IS NOT NULL THEN SELECT*INTO j FROM public.ty_ix_job WHERE id=NEW.job_id;IF j.connection_id<>r.connection_id OR j.profile_id<>r.profile_id OR j.kind<>'message.send'OR j.created_by<>r.approved_by OR j.request->>'source_kind'<>'workflow_notice'OR j.request->>'source_id'<>NEW.id::text OR(j.request->>'recipient_account_id')::bigint<>NEW.recipient_account_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 通知必须关联同一真实225投递任务';END IF;END IF;
  IF NEW.transport_receipt_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_ix_delivery_receipt z WHERE z.id=NEW.transport_receipt_id AND z.job_id=NEW.job_id AND z.connection_id=NEW.connection_id AND z.outcome='confirmed'AND z.remote_id=NEW.remote_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 通知受理事实须有对应225真实平台响应';END IF;
  IF TG_OP='UPDATE'AND(OLD.read_state='provider_reported_read'AND NEW.read_state<>OLD.read_state OR OLD.delivery_state='implied_by_read'AND NEW.delivery_state<>OLD.delivery_state OR OLD.acceptance_state='provider_accepted'AND NEW.acceptance_state<>OLD.acceptance_state OR OLD.reported_read_at IS NOT NULL AND(NEW.reported_read_at IS NULL OR NEW.reported_read_at<OLD.reported_read_at)OR OLD.observed_read_at IS NOT NULL AND NEW.observed_read_at IS DISTINCT FROM OLD.observed_read_at)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已核平台受理、阅读与首次观察事实不能倒退或换时';END IF;
  IF TG_OP='UPDATE'AND(to_jsonb(NEW)-ARRAY['identity_id','identity_revision','recipient_external_id','job_id','transport_receipt_id','state','acceptance_state','delivery_state','read_state','platform_result','reported_read_at','observed_read_at','remote_id','error_code','last_polled_at','revision'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['identity_id','identity_revision','recipient_external_id','job_id','transport_receipt_id','state','acceptance_state','delivery_state','read_state','platform_result','reported_read_at','observed_read_at','remote_id','error_code','last_polled_at','revision'])OR TG_OP='UPDATE'AND OLD.job_id IS NOT NULL AND ROW(NEW.job_id,NEW.identity_id,NEW.identity_revision,NEW.recipient_external_id)IS DISTINCT FROM ROW(OLD.job_id,OLD.identity_id,OLD.identity_revision,OLD.recipient_external_id)OR TG_OP='UPDATE'AND OLD.transport_receipt_id IS NOT NULL AND ROW(NEW.transport_receipt_id,NEW.remote_id)IS DISTINCT FROM ROW(OLD.transport_receipt_id,OLD.remote_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已排队通知的原单与收件映射不可改绑';END IF;
 ELSIF TG_TABLE_NAME='ty_nx_observation'THEN
  IF TG_OP='UPDATE'AND(to_jsonb(NEW)-ARRAY['delivery_id','state','error_code','applied_at','last_checked_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['delivery_id','state','error_code','applied_at','last_checked_at'])OR TG_OP='UPDATE'AND OLD.delivery_id IS NOT NULL AND NEW.delivery_id IS DISTINCT FROM OLD.delivery_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 平台回执原文与已确认关联不可改写';END IF;
  IF NEW.envelope_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_ix_callback_envelope x WHERE x.id=NEW.envelope_id AND x.connection_id=NEW.connection_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 平台回执须引用同连接已验签原件';END IF;
  IF NEW.receipt_job_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_nx_receipt_job x JOIN public.ty_nx_delivery z ON z.id=x.delivery_id WHERE x.id=NEW.receipt_job_id AND x.state='leased'AND z.connection_id=NEW.connection_id AND z.remote_id=NEW.remote_id AND z.recipient_external_id=NEW.recipient_external_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 主动回读回执须有同一消息和收件人的真实查询租约';END IF;
  IF NEW.delivery_id IS NOT NULL THEN SELECT*INTO d FROM public.ty_nx_delivery WHERE id=NEW.delivery_id;SELECT*INTO c FROM public.ty_integration_connection WHERE id=d.connection_id;IF d.connection_id<>NEW.connection_id OR d.remote_id IS DISTINCT FROM NEW.remote_id OR d.recipient_external_id IS DISTINCT FROM NEW.recipient_external_id OR c.provider<>NEW.provider THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 回执不得冒认其他企业消息或收件人';END IF;END IF;
 ELSIF TG_TABLE_NAME='ty_nx_receipt_job'THEN
  SELECT*INTO d FROM public.ty_nx_delivery WHERE id=NEW.delivery_id;
  IF d.remote_id IS NULL OR d.acceptance_state<>'provider_accepted'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 消息回执查询须引用实际已受理消息';END IF;
  IF TG_OP='INSERT'AND NEW.state<>'queued'OR TG_OP='UPDATE'AND((to_jsonb(NEW)-ARRAY['state','lease_token','lease_until','attempts','error_code','result','revision','completed_at'])IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','lease_token','lease_until','attempts','error_code','result','revision','completed_at'])OR NEW.revision<>OLD.revision+1 OR OLD.state NOT IN('queued','leased')OR OLD.state='queued'AND NEW.state NOT IN('leased','blocked')OR OLD.state='leased'AND NEW.state NOT IN('leased','completed','failed','blocked'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 回执查询来源与租约历史不可换绑或复活';END IF;
 END IF;RETURN NEW;END$$;
CREATE TRIGGER ty_nx_rule_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_nx_rule FOR EACH ROW EXECUTE FUNCTION fn_ty_nx_guard();
CREATE TRIGGER ty_nx_event_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_nx_event FOR EACH ROW EXECUTE FUNCTION fn_ty_nx_guard();
CREATE TRIGGER ty_nx_delivery_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_nx_delivery FOR EACH ROW EXECUTE FUNCTION fn_ty_nx_guard();
CREATE TRIGGER ty_nx_observation_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_nx_observation FOR EACH ROW EXECUTE FUNCTION fn_ty_nx_guard();
CREATE TRIGGER ty_nx_receipt_job_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_nx_receipt_job FOR EACH ROW EXECUTE FUNCTION fn_ty_nx_guard();
CREATE FUNCTION fn_ty_nx_receipt_proof()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE d public.ty_nx_delivery%ROWTYPE;
BEGIN SELECT*INTO d FROM public.ty_nx_delivery WHERE id=NEW.id;
 IF d.acceptance_state='provider_accepted'AND NOT EXISTS(SELECT 1 FROM public.ty_ix_delivery_receipt z WHERE z.id=d.transport_receipt_id AND z.job_id=d.job_id AND z.outcome='confirmed'AND z.remote_id=d.remote_id)OR d.read_state='provider_reported_read'AND NOT EXISTS(SELECT 1 FROM public.ty_nx_observation o WHERE o.delivery_id=d.id AND o.state='applied'AND o.kind='read'AND o.remote_id=d.remote_id AND o.recipient_external_id=d.recipient_external_id)OR d.read_state='provider_reported_unread'AND NOT EXISTS(SELECT 1 FROM public.ty_nx_observation o WHERE o.delivery_id=d.id AND o.state='applied'AND o.kind='unread')OR d.delivery_state='implied_by_read'AND d.read_state<>'provider_reported_read'OR d.reported_read_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_nx_observation o WHERE o.delivery_id=d.id AND o.state='applied'AND o.kind='read'AND o.reported_at=d.reported_read_at)OR d.observed_read_at IS NOT NULL AND d.read_state<>'provider_reported_read'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 平台受理或已读状态须有225真实投递或已验回执事实';END IF;
 RETURN NEW;END$$;
CREATE CONSTRAINT TRIGGER ty_nx_receipt_proof AFTER INSERT OR UPDATE ON ty_nx_delivery DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fn_ty_nx_receipt_proof();
CREATE INDEX ty_nx_dispatch ON ty_nx_event(state,id);
CREATE INDEX ty_nx_pending_receipts ON ty_nx_observation(state,last_checked_at,id);
